import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788526325000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>See the <a href="/reference/environment">environment variable reference</a> for the full table.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to “Connecting”">​</a></h2><p>Three variables are required — the host, the user and the password:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_HOST</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">imap.example.net</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_USER</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">me@example.net</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_PASSWORD</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">…</span></span></code></pre></div><p>Where the provider offers <strong>app passwords</strong>, use one. It is scoped to this server and can be revoked without changing the account password, which matters more than usual here: a mailbox password is often the account password.</p><p><code>IMAP_PASSWORD</code> is deleted from <code>process.env</code> as soon as it has been read, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p><code>IMAP_TLS</code> is <code>implicit</code> by default, which is port 993 and TLS from the first byte. <code>starttls</code> upgrades a plaintext connection on port 143, and <code>none</code> does not encrypt at all — the server warns loudly about that against anything but a loopback host, because the password and every message would cross the network in the clear.</p><p><code>IMAP_INSECURE_TLS=true</code> accepts a self-signed certificate. It is scoped to this connection, not <code>NODE_TLS_REJECT_UNAUTHORIZED</code>, so validation stays on for everything else in the process. Prefer adding the CA to the trust store.</p><h2 id="read-only-and-why-it-is-the-default" tabindex="-1">Read-only, and why it is the default <a class="header-anchor" href="#read-only-and-why-it-is-the-default" aria-label="Permalink to “Read-only, and why it is the default”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">false</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">   # registers the five mailbox write tools</span></span></code></pre></div><p><strong>It defaults to <code>true</code></strong>, unlike every other server in this family. That is not an oversight: this variable replaced <code>IMAP_ALLOW_WRITE</code>, which was opt-in, and a rename that quietly flipped the default would have handed write access to every installation that upgraded without reading the changelog. Only the literal string <code>false</code> turns it off.</p><p>An installation that still sets <code>IMAP_ALLOW_WRITE</code> <strong>refuses to start</strong>, with a message naming the replacement. Ignoring it would leave someone believing a protection is in force when it is not.</p><h2 id="turning-the-approval-dialog-off" tabindex="-1">Turning the approval dialog off <a class="header-anchor" href="#turning-the-approval-dialog-off" aria-label="Permalink to “Turning the approval dialog off”">​</a></h2><p><code>delete_messages</code>, <code>move_messages</code> and deleting a folder ask a person through MCP elicitation before they act. <code>ELICITATION=false</code> takes them to the two-call token instead. It does not remove the guard; there is no setting in which a guarded call goes unannounced.</p><p>The variable deliberately carries no <code>IMAP_</code> prefix, which means it reaches every MCP server in the same environment, and — like <code>IMAP_TLS</code>, unlike <code>IMAP_READ_ONLY</code> — a value it does not recognise <strong>stops the server</strong>. See <a href="/guide/approval">Asking a person</a>.</p><h2 id="reading-documents" tabindex="-1">Reading documents <a class="header-anchor" href="#reading-documents" aria-label="Permalink to “Reading documents”">​</a></h2><p>Nothing needs to be configured for it: <code>get_attachments</code> with <code>mode: &quot;text&quot;</code> reads the text out of a PDF, Word, Excel, PowerPoint or OpenDocument attachment.</p><p>It is worth knowing which of the three size limits applies, because they are separate on purpose. <code>IMAP_MAX_ATTACHMENT_BYTES</code> (1 MB) bounds what may come back inline, <code>IMAP_MAX_DOWNLOAD_BYTES</code> (25 MB) bounds what may be written to disk, and <code>IMAP_MAX_EXTRACT_BYTES</code> (10 MB, maximum 64 MB) bounds what is handed to the parser. Raising one is not a request to raise the others, and the last has a hard ceiling — a value above it stops the server rather than being quietly clamped.</p><p>If you run this server in a container or on another machine, prefer <code>mode: &quot;text&quot;</code> over <code>IMAP_DOWNLOAD_DIR</code>. A download directory is a path on the machine the server runs on; a client somewhere else gets that path back and can do nothing with it.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you — and by default it has already been made. <code>IMAP_ALLOW_TOOLS</code> and <code>IMAP_DENY_TOOLS</code> let you draw your own, on either side of it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">list_new_messages,get_message,move_messages</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">IMAP_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_messages</span></span></code></pre></div><p>Why bother, when all of them work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, the full set is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_thing</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset: <code>list_mailboxes</code>, <code>list_new_messages</code>, <code>list_messages</code>, <code>get_message</code>, <code>set_message_flags</code> and <code>move_messages</code>. It is marked per tool in the <a href="/reference/tools">tool reference</a>, generated from the same constant the filter reads, so the two cannot drift. It composes — naming a tool alongside it puts that one back, and <code>IMAP_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>IMAP_ALLOW_TOOLS</code> decides what is in; <code>IMAP_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>IMAP_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, which is what makes <code>get_*,move_*</code> a usable template for both kinds of deployment. <code>IMAP_ALLOW_TOOLS=essential</code> narrows to the read half of the preset — four of its six tools — which is why it stays a working combination on a server that is read-only unless told otherwise.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>IMAP_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div><h2 id="what-the-filter-does-not-cover" tabindex="-1">What the filter does not cover <a class="header-anchor" href="#what-the-filter-does-not-cover" aria-label="Permalink to “What the filter does not cover”">​</a></h2><p>Tools. This server also registers <strong>attachment resources</strong>, and <code>IMAP_ALLOW_TOOLS</code> does not touch those — it narrows <code>tools/list</code>, not <code>resources/list</code>. Worth knowing before you conclude that a filtered install reaches less of the mailbox than it does.</p>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};